        UNION { VALUES ?root { wd:Q12036252 wd:Q115135899 wd:Q160857 wd:Q12036470 wd:Q6865195 wd:Q27058556 wd:Q2306635 wd:Q17086317 wd:Q182854 wd:Q105688852 wd:Q108147401 wd:Q692457 wd:Q25100360 wd:Q79782 wd:Q110762908 wd:Q4298882 wd:Q3151 wd:Q200974 wd:Q946764 wd:Q6987233 } ?item wdt:P279 ?root }
        UNION { VALUES ?root { wd:Q12036252 wd:Q115135899 wd:Q160857 wd:Q12036470 wd:Q6865195 wd:Q27058556 wd:Q2306635 wd:Q17086317 wd:Q182854 wd:Q105688852 wd:Q108147401 wd:Q692457 wd:Q25100360 wd:Q79782 wd:Q110762908 wd:Q4298882 wd:Q3151 wd:Q200974 wd:Q946764 wd:Q6987233 } BIND(?root AS ?item) }
